#include <ncurses.h>

int main() {
    initscr();            // start ncurses
    noecho();             // don't print typed characters
    cbreak();             // disable line buffering

    mvaddch(5, 10, 'A');  // move and draw

    refresh();            // push changes to screen
    getch();              // wait for input

    endwin();             // clean up
    return 0;
}
